// Build a valid, readable, null-terminated wide string and call wcslen_fixed.
// We ensure the buffer is within reasonable bounds and properly terminated to avoid overread.
std::string seed = FUZZ_PARAM_STR();
size_t max_wc = 512; // keep allocations < 2048 bytes even on 4-byte wchar_t
size_t k = (*FUZZ_PARAM(unsigned int) % (max_wc + 1));
// Always allocate at least 1 for the terminator
if (k == 0) { k = 1; }
std::vector<wchar_t> ws(k + 1);
// Fill wide chars from seed bytes to produce varied code units while remaining deterministic for given seed
for (size_t i = 0; i < k; ++i) {
    unsigned char b0 = static_cast<unsigned char>(seed[i % seed.size()]);
    unsigned char b1 = static_cast<unsigned char>(seed[(i + 1) % seed.size()]);
    wchar_t v = static_cast<wchar_t>(((unsigned int)b1 << 8) ^ (unsigned int)b0);
    ws[i] = v ? v : L'A'; // avoid accidental early terminators in the body
}
ws[k] = L'\0';
size_t len = wcslen_fixed(ws.data());
// Validate the function did not read past our constructed terminator
FUZZ_ASSERT(len <= k, "wcslen_fixed length exceeds constructed buffer length");

// Generate two valid, readable, null-terminated wide strings and a bound n.
// Ensure both buffers are readable for at least n wide chars to satisfy API preconditions.
std::string s1b = FUZZ_PARAM_STR();
std::string s2b = FUZZ_PARAM_STR();
size_t n = (*FUZZ_PARAM(unsigned int) % 513); // compare up to 512 code units
size_t min_body = n; // ensure at least n readable code units before the terminator
size_t k1 = (*FUZZ_PARAM(unsigned int) % 512);
size_t k2 = (*FUZZ_PARAM(unsigned int) % 512);
if (k1 < min_body) k1 = min_body;
if (k2 < min_body) k2 = min_body;
std::vector<wchar_t> w1(k1 + 1);
std::vector<wchar_t> w2(k2 + 1);
for (size_t i = 0; i < k1; ++i) {
    unsigned char b0 = static_cast<unsigned char>(s1b[i % s1b.size()]);
    unsigned char b1 = static_cast<unsigned char>(s1b[(i + 3) % s1b.size()]);
    wchar_t v = static_cast<wchar_t>(((unsigned int)b1 << 8) ^ (unsigned int)b0);
    w1[i] = v ? v : L'B';
}
for (size_t i = 0; i < k2; ++i) {
    unsigned char b0 = static_cast<unsigned char>(s2b[i % s2b.size()]);
    unsigned char b1 = static_cast<unsigned char>(s2b[(i + 5) % s2b.size()]);
    wchar_t v = static_cast<wchar_t>(((unsigned int)b1 << 8) ^ (unsigned int)b0);
    w2[i] = v ? v : L'C';
}
w1[k1] = L'\0';
w2[k2] = L'\0';
int r12 = wcsncmp_fixed(w1.data(), w2.data(), n);
int r21 = wcsncmp_fixed(w2.data(), w1.data(), n);
// Property: antisymmetry like standard wcsncmp
FUZZ_ASSERT((r12 == 0 && r21 == 0) || (r12 < 0 && r21 > 0) || (r12 > 0 && r21 < 0), "wcsncmp_fixed antisymmetry violated");

// Construct haystack and needle as valid, null-terminated wide strings.
// Handle empty-needle case explicitly to exercise that path.
std::string hb = FUZZ_PARAM_STR();
std::string nb = FUZZ_PARAM_STR();
size_t hlen = (*FUZZ_PARAM(unsigned int) % 512) + 1; // ensure at least 1 code unit before terminator
size_t nlen_choice = (*FUZZ_PARAM(unsigned int) % 4); // 1-in-4 chance to make needle empty
size_t nlen = (nlen_choice == 0) ? 0 : ((*FUZZ_PARAM(unsigned int) % 64) + 1);
std::vector<wchar_t> hay(hlen + 1);
std::vector<wchar_t> ned(std::max<size_t>(nlen, 0) + 1);
for (size_t i = 0; i < hlen; ++i) {
    unsigned char b0 = static_cast<unsigned char>(hb[i % hb.size()]);
    unsigned char b1 = static_cast<unsigned char>(hb[(i + 7) % hb.size()]);
    wchar_t v = static_cast<wchar_t>(((unsigned int)b1 << 8) ^ (unsigned int)b0);
    hay[i] = v ? v : L'D';
}
hay[hlen] = L'\0';
for (size_t i = 0; i < nlen; ++i) {
    unsigned char b0 = static_cast<unsigned char>(nb[i % nb.size()]);
    unsigned char b1 = static_cast<unsigned char>(nb[(i + 11) % nb.size()]);
    wchar_t v = static_cast<wchar_t>(((unsigned int)b1 << 8) ^ (unsigned int)b0);
    ned[i] = v ? v : L'E';
}
ned[nlen] = L'\0';
wchar_t* p = wcsstr_fixed(hay.data(), ned.data());
if (nlen == 0) {
    // For empty needle, expect haystack per standard semantics
    FUZZ_ASSERT(p == hay.data(), "wcsstr_fixed should return haystack for empty needle");
} else if (p != nullptr) {
    // Validate that p lies within hay's bounds and matches needle
    FUZZ_ASSERT(p >= hay.data() && p <= hay.data() + hlen, "wcsstr_fixed returned pointer outside haystack");
    // Check the match region equals needle up to nlen
    for (size_t i = 0; i < nlen; ++i) {
        if (p + i > hay.data() + hlen) { FUZZ_BAIL(); }
        if (p[i] != ned[i]) { FUZZ_BAIL(); }
    }
} else {
    // NULL means no match; no additional checks needed
}

